// Project board — this app's MCP server. Centralu starts it (`node server.mjs`, stdio) when it is first
// needed and restarts it after the builder's turn when this folder changed.
// Edit this file, github.mjs and ui/index.html freely. Never edit runtime/ (generated by Centralu).
// Read AGENTS.md for the rules.
//
// The board is the GitHub Project named in project.json. GitHub is the only copy: every read asks
// GitHub (through the person's own `gh`, see github.mjs), with an in-memory cache of a few seconds,
// and every write goes straight to GitHub and is read back before the tool answers.
import { readFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { McpServer, serveStdio, z, centralu } from './runtime/centralu-app-runtime.mjs'
import {
  GitHubError,
  addContent,
  approveDeployments,
  createIssue,
  createPr,
  deleteBranch,
  editComment,
  dispatchWorkflow,
  findContent,
  mergePr,
  THREAD_MAX_COMMENTS,
  parseItemRef,
  pendingDeployments,
  postComment,
  readComment,
  prsWithHead,
  readBoard,
  readChecks,
  readIssueText,
  readJobLog,
  readPr,
  readRepo,
  readRepoFile,
  readRequired,
  readThread,
  resolveOption,
  resolveRef,
  runJobs,
  sameRepo,
  setOption,
  setPrBase,
  workflowRuns,
  viewerLogin,
  cancelWorkflowRun,
} from './github.mjs'
import { NO_PERMISSION, canMerge, cleanLog, clip, decideMerge, evaluateChecks, failureLineIndex, firstFailure, matchKnownFailure, squashMessage, workflowCheckNames } from './ci.mjs'
import { decisionSummary, renderInline, renderMarkdown } from './markdown.mjs'
import { DEFAULT_CONVENTIONS, commitProblems, englishProblems, fillTemplate, foreignBareIssueWarnings, normalizeWords, parseConventions, publicTextProblems, subjectProblems } from './rules.mjs'
import { answerFor, answerKey, commentIdOf, deleteAnswer, markRecorded, saveAnswer, unrecorded } from './answers.mjs'
import { GitError } from './git.mjs'
import { StackRefusal, rebaseStack } from './stack.mjs'
import { ReleaseRefusal, approveRelease, bumpRelease, cancelDuplicateRelease, guarded, rehearseRelease, releaseConfig, releaseStatus, tagRelease } from './release.mjs'
import { BUMPS } from './versions.mjs'

const UI = 'ui://project-board/index.html'

/**
 * What the view may load from outside: images on GitHub's own hosts, nothing else (no network, no
 * frames). `github.com/user-attachments/…` (an image pasted into an issue) redirects to
 * `private-user-images.githubusercontent.com`, and avatars and older uploads live on other
 * `githubusercontent.com` hosts. markdown.mjs writes an <img> only for these hosts; any other image
 * stays a link. Centralu reads this from the resource's contents (docs/apps.md §6.4).
 */
const VIEW_CSP = { resourceDomains: ['https://github.com', 'https://*.githubusercontent.com'] }

const config = await readFile(new URL('./project.json', import.meta.url), 'utf8')
  .then((t) => JSON.parse(t))
  .catch((e) => {
    console.error(`project.json could not be read: ${e.message}`)
    process.exit(1)
  })
for (const key of ['owner', 'number', 'repository', 'fields', 'decisionStatus']) {
  if (config[key] === undefined) {
    console.error(`project.json is missing "${key}"`)
    process.exit(1)
  }
}
const CACHE_MS = Math.max(0, Number(config.cacheSeconds ?? 30)) * 1000
// CI (ci_status, merge_when_green): which workflows hold the required checks, the issue that lists
// known intermittent failures, and how long merge_when_green may wait.
const CI = {
  workflows: config.ci?.workflows ?? ['.github/workflows/build.yml'],
  knownFailures: config.ci?.knownFailuresIssue ?? null,
  waitMinutes: Number(config.ci?.waitMinutes ?? 40),
  // PROJECT_BOARD_CI_POLL_MS: for the tests only, which cannot wait 30 s between polls
  pollMs: Number(process.env.PROJECT_BOARD_CI_POLL_MS) || Number(config.ci?.pollSeconds ?? 30) * 1000,
}

// --- The short cache -------------------------------------------------------------------------------
// One board in memory, for at most CACHE_MS. A write forgets it, and a read that started before a
// write never refills it (the generation check), so a tool never answers from a board older than
// its own last write.
let cache = null
let generation = 0
let inflight = null

async function board({ fresh = false } = {}) {
  if (!fresh && cache && cache.generation === generation && Date.now() - cache.at < CACHE_MS) return cache.board
  if (inflight && inflight.generation === generation) return inflight.promise
  const started = generation
  const promise = readBoard(config).then((b) => {
    if (started === generation) cache = { board: b, at: Date.now(), generation: started }
    return b
  })
  inflight = { generation: started, promise }
  promise.finally(() => {
    if (inflight?.promise === promise) inflight = null
  }).catch(() => {})
  return promise
}
const forget = () => {
  generation += 1
  cache = null
}

// --- One write at a time ---------------------------------------------------------------------------
// An agent may send several calls at once (a live Claude session sent both halves of a round trip
// in parallel). Each write reads the item fresh, so running them in arrival order keeps every
// "from → to" true and the last call the one that wins. A batch is one call: its items run in the
// order given, and no other write runs in between.
let writes = Promise.resolve()
function oneAtATime(fn) {
  const run = writes.then(fn, fn)
  writes = run.catch(() => {})
  return run
}

// --- Presenting ------------------------------------------------------------------------------------
// What the model reads is short: one line per item, and the same words in the text and in
// structuredContent (docs/apps.md §9.2: Claude Code hands the model the structured part, not the
// text). URLs and ids only when `detail: "full"` asks for them.
const FIELDS = ['status', 'priority', 'area']
const TYPE = { issue: 'issue', pull: 'pull request', draft: 'draft issue', hidden: 'hidden item' }
const refOf = (repo, number) => (sameRepo(repo, config.repository) ? `#${number}` : `${repo}#${number}`)
const ref = (item) => (item.number == null ? TYPE[item.type] : refOf(item.repository, item.number))
const label = (item) => `${ref(item)} ${item.title}`
const none = (v) => v ?? '(none)'
/** `#113 Narrow-window reading — Needs decision · Medium · UI`; a pull request says so. */
const line = (item) =>
  `${label(item)}${item.type === 'pull' ? (item.draft ? ' (draft PR)' : ' (PR)') : ''} — ${none(item.status)} · ${none(item.priority)} · ${none(item.area)}`
const fullLine = (item) =>
  `${line(item)} · ${TYPE[item.type]}${item.state ? ` ${item.state.toLowerCase()}` : ''}${item.url ? ` · ${item.url}` : ''} · item ${item.itemId}`

/** Status columns in the project's own order, with the decision column first. */
function columns(b) {
  const names = b.fields.status.options.map((o) => o.name)
  const first = names.find((n) => n.toLowerCase() === String(config.decisionStatus).toLowerCase())
  return first ? [first, ...names.filter((n) => n !== first)] : names
}
const where = (b) => `${b.project.title} (GitHub Project #${b.project.number} of ${b.project.owner}), read from GitHub at ${b.fetchedAt}`
const RANK = { High: 0, Medium: 1, Low: 2 }
const byPriority = (a, b) => (RANK[a.priority] ?? 3) - (RANK[b.priority] ?? 3) || (a.number ?? 0) - (b.number ?? 0)

/**
 * One answer: the text, and the same words first in structuredContent (`summary`). A session's
 * client may hand the model the structured part instead of the text (Claude Code does, seen in a
 * live session), and what a write changed must reach the model either way.
 */
const answer = (t, structured, summary = t) => ({ content: [{ type: 'text', text: t }], structuredContent: { summary, ...structured } })

/**
 * An answer made of a summary and lists of lines. The text is the summary, then each list's lines
 * (under its heading, if it has one; an `inline` list is one line after its heading), so it says
 * exactly what the structured part says.
 */
function linesAnswer(summary, lists, extra = {}) {
  const structured = {}
  const text = [summary]
  for (const [key, heading, lines, inline] of lists) {
    if (!lines.length) continue
    structured[key] = lines
    if (inline) text.push(`${heading} ${lines.join(', ')}.`)
    else text.push(...(heading ? [heading] : []), ...lines)
  }
  return answer(text.join('\n'), { ...structured, ...extra }, summary)
}

/** A failure as an answer: the message says what happened and what to do, and nothing changed. */
function failure(e, prefix = '') {
  const message = `${prefix}${reason(e)}`
  return { isError: true, ...answer(message, { error: { kind: e instanceof GitHubError ? e.kind : 'internal', message } }) }
}
function reason(e) {
  if (e instanceof GitHubError) return e.message
  console.error(e)
  return `Unexpected error: ${e?.message ?? e}`
}

// --- Reading items by number ------------------------------------------------------------------------
const itemRef = z.union([z.string(), z.number()])
const REF_HELP = '8, "#8", "owner/repo#8" or its URL'
const detailInput = z.enum(['compact', 'full']).optional().describe('"full" adds type, state, URL and ids; default "compact"')

const matches = (want) => (i) => i.number === want.number && sameRepo(i.repository, want.repo)

/**
 * Finds the items asked for, in the order asked, once each. A reference that is not an issue or pull
 * request fails the whole read (the model sent something wrong); one that is not in the project is
 * named in `missing`.
 */
function pick(b, inputs) {
  const found = []
  const missing = []
  const seen = new Set()
  for (const input of inputs) {
    const want = parseItemRef(input, config.repository)
    const key = `${want.repo.toLowerCase()}#${want.number}`
    if (seen.has(key)) continue
    seen.add(key)
    const item = b.items.find(matches(want))
    if (item) found.push(item)
    else missing.push(refOf(want.repo, want.number))
  }
  return { found, missing }
}

/** The read tools' answer: compact lines, or with `full` the whole items and where they came from. */
function itemsAnswer(b, summary, items, detail, extra = [], suffix = () => '') {
  const full = detail === 'full'
  const lists = [['items', '', items.map((i) => `${(full ? fullLine : line)(i)}${suffix(i)}`)], ...extra]
  if (!full) return linesAnswer(summary, lists)
  const a = linesAnswer(`${summary} ${where(b)}.`, lists, { project: b.project, fetchedAt: b.fetchedAt })
  a.structuredContent.items = items
  return a
}

// --- Writing: one item or a batch -------------------------------------------------------------------
const fieldInputs = {
  status: z.string().optional().describe('Status, for example "Ready" or "In review"'),
  priority: z.string().optional().describe('Priority: High, Medium or Low'),
  area: z.string().optional().describe('Area, for example "UI" or "Apps"'),
}
const batchInputs = (verb) => ({
  item: itemRef.optional().describe(`One issue or pull request: ${REF_HELP}`),
  items: z
    .array(z.union([itemRef, z.object({ item: itemRef, ...fieldInputs })]))
    .min(1)
    .max(50)
    .optional()
    .describe(`Several, ${verb} in this order: each ${REF_HELP}, or { item, status?, priority?, area? }`),
  ...fieldInputs,
})

// Failures after which the next items would fail the same way: stop there instead of repeating it.
const STOPS = new Set(['network', 'auth', 'scope', 'gh-missing', 'setup', 'forbidden', 'internal'])
const stops = (e) => STOPS.has(e instanceof GitHubError ? e.kind : 'internal')

/**
 * Turns `item` or `items` (plus the top-level fields, which apply to every entry that does not set
 * its own) into a list of entries, and checks every reference and option name before anything is
 * written: one wrong name changes nothing, and the answer says each problem once.
 */
function plan(b, { item, items, status, priority, area }, { needFields }) {
  if (item !== undefined && items !== undefined) throw new GitHubError('input', 'Give item (one) or items (a list), not both. Nothing changed.')
  if (item === undefined && items === undefined) throw new GitHubError('input', 'Give item (one) or items (a list). Nothing changed.')
  const shared = { status, priority, area }
  const problems = []
  const entries = (items ?? [item]).map((raw) => {
    const e = raw !== null && typeof raw === 'object' ? raw : { item: raw }
    const entry = { input: e.item, options: {} }
    try {
      entry.want = parseItemRef(e.item, config.repository)
      entry.ref = refOf(entry.want.repo, entry.want.number)
    } catch (err) {
      problems.push(err.message)
      return entry
    }
    let any = false
    for (const key of FIELDS) {
      const value = e[key] ?? shared[key]
      if (value === undefined) continue
      any = true
      try {
        entry.options[key] = resolveOption(b.fields[key], value)
      } catch (err) {
        problems.push(err.message)
      }
    }
    if (needFields && !any) problems.push(`Nothing to change for ${entry.ref}: give status, priority or area.`)
    return entry
  })
  if (problems.length) throw new GitHubError('input', `${[...new Set(problems)].join(' ')} Nothing changed.`)
  return entries
}

const change = (d) => `${d.field} ${none(d.from)} → ${d.to}`

/**
 * Applies the planned options to one item, one field at a time, skipping a field that already has
 * the value. `item` is this batch's own copy, updated after each write so a later entry for the
 * same item starts from the truth. A failed write carries what was done.
 */
async function writeFields(b, item, options) {
  const done = []
  const same = []
  for (const key of FIELDS) {
    const option = options[key]
    if (!option) continue
    const field = b.fields[key].name
    if (item[key] === option.name) {
      same.push(`${field} already ${option.name}`)
      continue
    }
    try {
      await setOption(b.project.id, item.itemId, b.fields[key].id, option.id)
    } catch (e) {
      e.done = done
      throw e
    } finally {
      // Whether or not this write landed, the cached board can no longer be trusted.
      forget()
    }
    done.push({ field, from: item[key], to: option.name })
    item[key] = option.name
  }
  return { done, same }
}

/**
 * GitHub can take a moment to list an item that was just added: on 2026-10-04 the read right after
 * `addProjectV2ItemById` came back without it four times in a row, and a second read a few seconds
 * later had it. So a read that looks for items tries a few times, with short waits.
 */
const LIST_WAITS_MS = [0, 500, 1000, 1500, 2000]
async function findFresh(itemIds) {
  let last
  for (const ms of LIST_WAITS_MS) {
    if (ms) await new Promise((r) => setTimeout(r, ms))
    last = await board({ fresh: true })
    if (itemIds.every((id) => last.items.some((i) => i.itemId === id))) break
  }
  return { board: last, byId: new Map(last.items.map((i) => [i.itemId, i])) }
}

/**
 * Reads the touched items again, fresh, once for the whole batch, and adds to each line what
 * GitHub shows when it is not what was set. It never throws: by now something may have been
 * written, and a failed read must not hide that. Returns the summary's last words.
 */
async function readBack(rows) {
  // Only items that answer with a line: a failed one's line already says how far it got.
  const touched = rows.filter((r) => r.line && r.touched)
  if (!touched.length) return ''
  let byId
  try {
    ;({ byId } = await findFresh(touched.map((r) => r.itemId)))
  } catch (e) {
    return ` Reading it back from GitHub failed: ${e?.message ?? e}`
  }
  // A batch may name the same item twice: each field is checked on the last line that set it.
  const last = new Map()
  for (const r of touched) for (const k of FIELDS) if (r.options[k]) last.set(`${r.itemId} ${k}`, r)
  let off = 0
  for (const r of touched) {
    const now = byId.get(r.itemId)
    if (!now) {
      off += 1
      r.line += ' (GitHub did not list it when read back; look again in a moment)'
      continue
    }
    const wrong = FIELDS.filter((k) => last.get(`${r.itemId} ${k}`) === r && now[k] !== r.options[k].name).map((k) => `${r.fieldNames[k]} ${none(now[k])}`)
    if (wrong.length) {
      off += 1
      r.line += ` (but GitHub now shows ${wrong.join(', ')})`
    }
  }
  return off ? ` Read back from GitHub: ${off} differ${off === 1 ? 's' : ''}, see the line${off === 1 ? '' : 's'}.` : ' Read back from GitHub: as set.'
}

const count = (n, word) => (n ? [`${n} ${word}`] : [])

/** The answer of a write: one line per item, the failures, and `isError` only when nothing worked. */
function writeAnswer(b, ok, counts, failed, tail) {
  const summary = `Project ${b.project.title} on GitHub: ${[...counts, ...count(failed.length, 'failed')].join(', ')}.${tail}`
  const a = linesAnswer(summary, [
    ['results', '', ok.map((r) => r.line)],
    ['failed', 'Failed:', failed],
  ])
  return ok.length === 0 && failed.length ? { isError: true, ...a } : a
}

/** Records a failed entry, and when it means the rest would fail too, the entries not tried. */
function fail(failed, entries, i, text, e) {
  failed.push(text)
  if (!stops(e)) return false
  const rest = entries.slice(i + 1).map((x) => x.ref)
  if (rest.length) failed.push(`Not tried after that: ${rest.join(', ')}.`)
  return true
}

const fieldNamesOf = (b) => Object.fromEntries(FIELDS.map((k) => [k, b.fields[k].name]))

// The two writes. Registered below; each runs inside oneAtATime.
async function setItemFields(args) {
  let b, entries
  try {
    b = await board({ fresh: true })
    entries = plan(b, args, { needFields: true })
  } catch (e) {
    return failure(e)
  }
  const items = b.items.map((i) => ({ ...i }))
  const rows = []
  const failed = []
  for (const [i, e] of entries.entries()) {
    let item = items.find(matches(e.want))
    let added = false
    if (!item) {
      try {
        const content = await findContent(e.want.repo, e.want.number)
        if (!content) {
          failed.push(`${e.ref} is not an issue or pull request this GitHub login can see. Nothing added.`)
          continue
        }
        const itemId = await addContent(b.project.id, content.id)
        if (!itemId) throw new GitHubError('github', `GitHub did not return the project item it added for ${e.ref}.`)
        forget()
        item = {
          itemId,
          type: content.type,
          number: content.number,
          title: content.title,
          url: content.url,
          state: null,
          draft: false,
          repository: e.want.repo,
          status: null,
          priority: null,
          area: null,
        }
        items.push(item)
        added = true
      } catch (err) {
        if (fail(failed, entries, i, `${e.ref}: ${reason(err)}`, err)) break
        continue
      }
    }
    const row = { itemId: item.itemId, options: e.options, fieldNames: fieldNamesOf(b) }
    try {
      const { done, same } = await writeFields(b, item, e.options)
      row.touched = done.length > 0
      row.line = done.length ? [`${e.ref}${added ? ' added' : ''} ${done.map(change).join(', ')}`, ...same].join('; ') : `${e.ref}${added ? ' added' : ''} unchanged: ${same.join(', ')}`
      rows.push(row)
    } catch (err) {
      const done = err.done ?? []
      if (fail(failed, entries, i, `${e.ref}: ${done.length ? `${done.map(change).join(', ')} done, then ` : ''}${reason(err)}`, err)) break
    }
  }
  const tail = await readBack(rows)
  const ok = rows.filter((r) => r.line)
  return writeAnswer(b, ok, [...count(ok.filter((r) => r.touched).length, 'changed'), ...count(ok.filter((r) => !r.touched).length, 'unchanged')], failed, tail)
}

async function addItem(args) {
  let b, entries
  try {
    b = await board({ fresh: true })
    entries = plan(b, args, { needFields: false })
  } catch (e) {
    return failure(e)
  }
  const rows = []
  const failed = []
  // One holder per project item, shared by every entry that names it: an item is added once, and a
  // later entry's "from" is what an earlier one set.
  const holders = new Map()
  let stopped = null
  // First every add, in order.
  for (const [i, e] of entries.entries()) {
    const key = `${e.want.repo.toLowerCase()}#${e.want.number}`
    const row = { options: e.options, fieldNames: fieldNamesOf(b), head: `${e.ref} already in the project` }
    let holder = holders.get(key)
    if (!holder) {
      const existing = b.items.find(matches(e.want))
      if (existing) holder = { itemId: existing.itemId, item: { ...existing } }
      else {
        try {
          const content = await findContent(e.want.repo, e.want.number)
          if (!content) {
            failed.push(`${e.ref} is not an issue or pull request this GitHub login can see. Nothing added.`)
            continue
          }
          holder = { itemId: await addContent(b.project.id, content.id), added: true }
          forget()
          Object.assign(row, { added: true, touched: true, head: `${e.ref} added: ${content.title}${content.type === 'pull' ? ' (PR)' : ''}` })
        } catch (err) {
          if (fail(failed, entries, i, `${e.ref}: ${reason(err)} Nothing added.`, err)) {
            stopped = 'its fields were not set after the failure above'
            break
          }
          continue
        }
      }
      holders.set(key, holder)
    }
    Object.assign(row, { holder, itemId: holder.itemId })
    rows.push(row)
  }
  // Then the fields, in the same order. A new item's current values come from GitHub, which may
  // list it only a moment later (findFresh), so every "from" is what GitHub had.
  const toSet = rows.filter((r) => Object.keys(r.options).length)
  const unlisted = [...new Set(toSet.map((r) => r.holder))].filter((h) => !h.item)
  if (!stopped && unlisted.length) {
    try {
      const { byId } = await findFresh(unlisted.map((h) => h.itemId))
      for (const h of unlisted) if (byId.has(h.itemId)) h.item = { ...byId.get(h.itemId) }
    } catch (err) {
      stopped = `reading the project back failed, so its fields were not set: ${reason(err)}`
    }
  }
  for (const r of toSet) {
    const why = stopped ?? (r.holder.item ? null : 'GitHub did not list it yet, so its fields were not set; set them with set_item_fields in a moment')
    if (why) {
      r.failed = true
      failed.push(`${r.head}; ${why}.`)
      continue
    }
    try {
      const { done, same } = await writeFields(b, r.holder.item, r.options)
      if (done.length) r.touched = true
      r.line = [r.head, ...(done.length ? [done.map(change).join(', ')] : []), ...same].join('; ')
    } catch (err) {
      const done = err.done ?? []
      r.failed = true
      failed.push(`${r.head}; ${done.length ? `${done.map(change).join(', ')} done, then ` : ''}${reason(err)}`)
      if (stops(err)) stopped = 'its fields were not set after the failure above'
    }
  }
  for (const r of rows) if (!r.line && !r.failed) r.line = r.added ? r.head : `${r.head}, nothing added`
  const tail = await readBack(rows)
  const ok = rows.filter((r) => r.line)
  return writeAnswer(b, ok, [...count(ok.filter((r) => r.added).length, 'added'), ...count(ok.filter((r) => !r.added).length, 'already in the project')], failed, tail)
}

// --- CI: ci_status and merge_when_green -------------------------------------------------------------
// The decisions are pure functions in ci.mjs; this part reads GitHub, asks them, and says the answer
// in a few lines. The rule both tools keep (#386): green means every required check is reported and
// passed. No checks reported, or any still running, is not green.

const MAX_LOGS = 4
const KNOWN_TTL_MS = 5 * 60_000
let known = null

/** The issue listing known intermittent failures (project.json ci.knownFailuresIssue), kept 5 minutes. */
async function knownFailures() {
  if (known && Date.now() - known.at < KNOWN_TTL_MS) return known
  known = { at: Date.now(), ...(await readIssueText(config.repository, CI.knownFailures)) }
  return known
}

const sha7 = (s) => (s ? String(s).slice(0, 7) : '?')

function rowState(r) {
  const c = r.check
  if (r.state === 'missing') return 'not reported yet'
  if (r.state === 'pending') return `pending (${c?.status ?? c?.state ?? 'waiting'})`
  if (r.state === 'failed') return c?.conclusion && c.conclusion !== 'failure' ? `failed (${c.conclusion})` : 'failed'
  return c?.conclusion && c.conclusion !== 'success' ? `passed (${c.conclusion})` : 'passed'
}

/**
 * For each failed check (required first, at most MAX_LOGS logs read): the first failing test line
 * of its job log, the error after it, and whether the known-failures issue quotes it. Whether it is
 * that flake stays the reader's call; the line says what matched.
 */
async function failureDetails(repo, checks) {
  const failed = [...checks.rows, ...checks.others].filter((r) => r.state === 'failed')
  const lines = []
  let issue = null
  let issueError = null
  for (const [i, r] of failed.entries()) {
    const job = r.check?.jobId ?? null
    const head = `${r.name}${checks.rows.includes(r) ? '' : ' (not required)'}${job ? ` (job ${job})` : ''}:`
    if (!job) {
      lines.push(`${head} not a GitHub Actions job, so no log${r.check?.url ? `; see ${r.check.url}` : ''}.`)
      continue
    }
    if (i >= MAX_LOGS) {
      lines.push(`${head} log not read (only the first ${MAX_LOGS} failures are).`)
      continue
    }
    let f
    try {
      f = firstFailure(await readJobLog(repo, job))
    } catch (e) {
      if (e instanceof GitHubError && ['network', 'auth', 'gh-missing'].includes(e.kind)) throw e
      lines.push(`${head} ${reason(e)}`)
      continue
    }
    let tail = ''
    if (CI.knownFailures && sameRepo(repo, config.repository) && (f.line || f.error)) {
      if (!issue && !issueError) {
        try {
          issue = await knownFailures()
        } catch (e) {
          issueError = reason(e)
        }
      }
      const match = issue ? matchKnownFailure(f, issue.text) : null
      if (match) tail = ` | known intermittent failure? #${CI.knownFailures}${issue.state === 'CLOSED' ? ' (closed)' : ''} quotes "${match}"`
      else if (issueError) tail = ` | #${CI.knownFailures} could not be read: ${clip(issueError, 120)}`
    }
    lines.push(`${head} ${f.line ?? 'no failing test line found'}${f.error ? ` | ${f.error}` : ''}${tail}`)
  }
  return lines
}

/** The CI part of an answer: a summary, then one line per check that is not passed, then failures. */
function ciLines(what, sha, req, checks, failures = [], detail = 'compact') {
  const c = checks.counts
  const parts = [`${c.passed}/${c.total} passed`, ...(c.failed ? [`${c.failed} failed`] : []), ...(c.pending ? [`${c.pending} pending`] : []), ...(c.missing ? [`${c.missing} not reported yet`] : [])]
  const summary = `${what} at ${sha7(sha)}: ${checks.verdict} — ${parts.join(', ')}.`
  const lines = checks.rows.filter((r) => r.state !== 'passed').map((r) => `${r.name}: ${rowState(r)}`)
  const passed = checks.rows.filter((r) => r.state === 'passed').map((r) => r.name)
  if (detail === 'full' && passed.length) lines.push(`Passed: ${passed.join(', ')}.`)
  if (detail === 'full' || req.added > 0) lines.push(`Required: ${req.source}.`)
  if (req.unresolved.length) lines.push(`Could not name the checks of ${req.unresolved.join(', ')}, so every reported check counts as required.`)
  if (detail === 'full' && checks.others.length) lines.push(`Not required: ${checks.others.map((r) => `${r.name} ${rowState(r)}`).join(', ')}.`)
  return { summary, checks: lines, failures }
}

/** An answer whose text is the summary, the check lines and the failures, as its structured part says. */
function ciAnswer(summary, ci, extra = {}, { isError = false } = {}) {
  const text = [summary, ...ci.checks, ...(ci.failures.length ? ['Failures:', ...ci.failures] : [])]
  const a = answer(text.join('\n'), { ...extra, checks: ci.checks, ...(ci.failures.length ? { failures: ci.failures } : {}) }, summary)
  return isError ? { isError: true, ...a } : a
}

async function evaluate(repo, sha, req) {
  return evaluateChecks({ required: req.names, reported: await readChecks(repo, sha), alsoReported: req.unresolved.length > 0 })
}

async function ciStatus({ pr, ref, repo, detail = 'compact' }) {
  if ((pr === undefined) === (ref === undefined)) throw new GitHubError('input', 'Give pr (a pull request) or ref (a branch, tag or commit), one of them.')
  let what, sha, base, target
  if (pr !== undefined) {
    const want = parseItemRef(pr, config.repository)
    target = want.repo
    const p = await readPr(target, want.number)
    what = `PR ${refOf(target, p.number)}${p.state === 'OPEN' ? '' : ` (${String(p.state).toLowerCase()})`}`
    sha = p.headRefOid
    base = p.baseRefName
  } else {
    target = repo ?? config.repository
    const [r, resolved] = await Promise.all([readRepo(target), resolveRef(target, ref)])
    what = `${sameRepo(target, config.repository) ? '' : `${target} `}${ref}`
    sha = resolved
    base = r.defaultBranch
  }
  const req = await readRequired(target, base, CI.workflows, workflowCheckNames, pr !== undefined ? sha : undefined)
  const checks = await evaluate(target, sha, req)
  const ci = ciLines(what, sha, req, checks, await failureDetails(target, checks), detail)
  return ciAnswer(ci.summary, ci, { verdict: checks.verdict, head: sha })
}

/** Sleeps, or stops early when the call is cancelled. Answers false when cancelled. */
function sleep(ms, signal) {
  if (signal?.aborted) return Promise.resolve(false)
  return new Promise((resolve) => {
    const t = setTimeout(() => (signal?.removeEventListener('abort', stop), resolve(true)), ms)
    const stop = () => (clearTimeout(t), resolve(false))
    signal?.addEventListener('abort', stop, { once: true })
  })
}

/**
 * Tells the caller the call is alive. Centralu ends a call after 10 minutes without progress
 * (docs/apps.md §5), and a wait for CI runs up to 40; the message shows under the session's tool card.
 */
function progress(ctx, n, message) {
  console.error(`[project-board] ${message}`)
  const token = ctx?.mcpReq?._meta?.progressToken
  if (token === undefined || typeof ctx?.mcpReq?.notify !== 'function') return
  void ctx.mcpReq.notify({ method: 'notifications/progress', params: { progressToken: token, progress: n, message } }).catch(() => {})
}

// GitHub works out whether a PR can be merged when asked, within seconds: a few short retries first.
const MERGEABLE_RETRIES = 3
const MERGEABLE_WAIT_MS = 2_000
const span = (ms) => (ms < 120_000 ? `${Math.round(ms / 1000)} s` : `${Math.round(ms / 60_000)} min`)

async function mergeWhenGreen({ pr, body, wait = false, waitMinutes, deleteBranch: del = false, detail = 'compact' }, ctx) {
  const want = parseItemRef(pr, config.repository)
  const repo = want.repo
  const what = `PR ${refOf(repo, want.number)}`
  const refused = (reason, ci, extra = {}) =>
    ci ? ciAnswer(`Not merged: ${reason}`, ci, { outcome: 'refused', merged: false, ...extra }, { isError: true }) : { isError: true, ...answer(`Not merged: ${reason}`, { outcome: 'refused', merged: false, ...extra }) }

  // Who is asking comes first: a contributor's agent gets no further (#386, merge policy).
  const { permissions } = await readRepo(repo)
  if (!canMerge(permissions)) return refused(NO_PERMISSION.reason, null, { kind: 'permission' })

  let p = await readPr(repo, want.number)
  const firstHead = p.headRefOid
  const req = await readRequired(repo, p.baseRefName, CI.workflows, workflowCheckNames, p.headRefOid)
  const limitMs = Math.min(60, Math.max(0, Number(waitMinutes ?? CI.waitMinutes) || 0)) * 60_000
  const started = Date.now()
  const signal = ctx?.mcpReq?.signal
  let quick = 0
  let beat = 0
  for (;;) {
    const checks = await evaluate(repo, p.headRefOid, req)
    const d = decideMerge({ permissions, pr: p, checks })
    if (d.action === 'refuse') {
      const ci = ciLines(what, p.headRefOid, req, checks, d.kind === 'failing' ? await failureDetails(repo, checks) : [], detail)
      return refused(d.reason, ci, { kind: d.kind, verdict: checks.verdict })
    }
    if (d.action === 'merge') return doMerge(repo, what, p, body, del, ciLines(what, p.headRefOid, req, checks, [], detail))
    // wait
    let pause = CI.pollMs
    if (d.kind === 'mergeable' && quick < MERGEABLE_RETRIES) {
      quick += 1
      pause = MERGEABLE_WAIT_MS
    } else if (!wait) {
      const ci = ciLines(what, p.headRefOid, req, checks, [], detail)
      return ciAnswer(`Not merged yet: ${d.reason} Call again later, or with wait: true to wait for them.`, ci, { outcome: 'pending', merged: false, verdict: checks.verdict })
    } else if (Date.now() - started + pause > limitMs) {
      const ci = ciLines(what, p.headRefOid, req, checks, [], detail)
      return ciAnswer(`Not merged: still not green after ${span(Date.now() - started)} of waiting (limit ${span(limitMs)}). ${d.reason}`, ci, {
        outcome: 'timeout',
        merged: false,
        verdict: checks.verdict,
      })
    } else {
      beat += 1
      progress(ctx, beat, `Waiting for ${what} (${span(Date.now() - started)} so far): ${d.reason}`)
    }
    if (!(await sleep(pause, signal))) return { isError: true, ...answer('Not merged: cancelled while waiting.', { outcome: 'cancelled', merged: false }) }
    p = await readPr(repo, want.number)
    if (p.headRefOid !== firstHead)
      return refused(`its head moved from ${sha7(firstHead)} to ${sha7(p.headRefOid)} while waiting, so the checks waited on are not the ones that count. Call again to wait on the new commit.`, null, { kind: 'moved' })
  }
}

async function doMerge(repo, what, p, body, del, ci) {
  const msg = squashMessage({ number: p.number, title: p.title, body, description: p.body })
  const why = await mergePr(repo, p.number, p.headRefOid, msg.subject, msg.body)
  if (why) return ciAnswer(`Not merged: GitHub refused the merge: ${why}`, ci, { outcome: 'refused', merged: false, kind: 'github' }, { isError: true })
  let commit = null
  try {
    commit = (await readPr(repo, p.number)).mergeCommit?.oid ?? null
  } catch {
    // merged either way; the commit id is a nicety
  }
  const extra = []
  if (del) {
    if (p.isCrossRepository) extra.push(`Branch ${p.headRefName} not deleted: it is in a fork.`)
    else {
      const e = await deleteBranch(repo, p.headRefName)
      extra.push(e ? `Branch ${p.headRefName} not deleted: ${e}` : `Deleted branch ${p.headRefName}.`)
    }
  }
  const summary = `Merged ${what} (squash) as ${sha7(commit)}: "${msg.subject}".${extra.length ? ` ${extra.join(' ')}` : ''}`
  return ciAnswer(summary, ci, { outcome: 'merged', merged: true, commit, subject: msg.subject })
}

// --- The reader: an item's thread, read in the view -------------------------------------------------
// The view shows an issue or pull request (body, comments, labels, board fields) without the browser,
// and answers a "Needs decision" item with a comment. Threads are cached like the board: in memory,
// for CACHE_MS, at most THREADS_MAX of them; a comment posted forgets its thread, and a read that
// started before the post never refills it.

const THREADS_MAX = 40
const threads = new Map() // key → { at, thread }, oldest first
const threadReads = new Map() // key → { version, promise }
const threadVersions = new Map() // key → how many comments this server posted there
const threadKey = (repo, number) => `${String(repo).toLowerCase()}#${number}`

async function thread(repo, number, { fresh = false } = {}) {
  const key = threadKey(repo, number)
  const hit = threads.get(key)
  if (!fresh && hit && Date.now() - hit.at < CACHE_MS) return hit.thread
  const version = threadVersions.get(key) ?? 0
  const pending = threadReads.get(key)
  if (pending && pending.version === version) return pending.promise
  const promise = readThread(repo, number).then((t) => {
    if (t && (threadVersions.get(key) ?? 0) === version) {
      threads.delete(key)
      threads.set(key, { at: Date.now(), thread: t })
      while (threads.size > THREADS_MAX) threads.delete(threads.keys().next().value)
    }
    return t
  })
  threadReads.set(key, { version, promise })
  promise
    .finally(() => {
      if (threadReads.get(key)?.promise === promise) threadReads.delete(key)
    })
    .catch(() => {})
  return promise
}
function forgetThread(repo, number) {
  const key = threadKey(repo, number)
  threads.delete(key)
  threadVersions.set(key, (threadVersions.get(key) ?? 0) + 1)
}

// Rendered once per body: the same thread read again from the cache is not rendered again
const rendered = new WeakMap()
function html(holder, text, opts) {
  let h = rendered.get(holder)
  if (h === undefined) {
    h = renderMarkdown(text, opts)
    rendered.set(holder, h)
  }
  return h
}
const renderOpts = (t) => ({ repo: t.repository, base: t.url })

/** A decision summary's fields as inline HTML, for the view's "Needs decision" list and the reader. */
function summaryView(s, opts) {
  if (!s) return null
  const inline = (v) => (v ? renderInline(v, { ...opts, breaks: true }) : null)
  return { date: s.date, question: inline(s.question), options: inline(s.options), recommendation: inline(s.recommendation), url: s.url, answered: s.answered }
}

const DEFAULT_COMMENTS = 50
const fieldsOf = (item) => ({ status: item?.status ?? null, priority: item?.priority ?? null, area: item?.area ?? null })

/** Failures the view shows in place of the item: as data, like `show`, so it can say why. */
function viewFailure(e) {
  const f = failure(e)
  return { content: f.content, structuredContent: { ok: false, ...f.structuredContent } }
}

async function readItem({ item, refresh, comments }) {
  const want = parseItemRef(item, config.repository)
  const [t, b] = await Promise.all([thread(want.repo, want.number, { fresh: refresh === true }), board().catch(() => null)])
  const ref = refOf(want.repo, want.number)
  if (!t) throw new GitHubError('not-found', `${ref} is not an issue or pull request this GitHub login can see.`)
  const onBoard = b?.items.find(matches(want)) ?? null
  const limit = Math.min(THREAD_MAX_COMMENTS, Math.max(1, Math.floor(comments ?? DEFAULT_COMMENTS)))
  const opts = renderOpts(t)
  const shown = t.comments.slice(-limit)
  const decision = onBoard?.status != null && onBoard.status.toLowerCase() === String(config.decisionStatus).toLowerCase()
  const kind = t.type === 'pull' ? 'pull request' : 'issue'
  const summary = `${ref} ${t.title} (${kind}, ${t.state.toLowerCase()}): ${t.totalComments} comment${t.totalComments === 1 ? '' : 's'}, ${shown.length} shown.`
  return answer(summary, {
    ok: true,
    item: {
      ref,
      type: t.type,
      repository: t.repository,
      number: t.number,
      title: t.title,
      url: t.url,
      state: t.state,
      stateReason: t.stateReason,
      draft: t.draft,
      author: t.author,
      createdAt: t.createdAt,
      labels: t.labels,
      inProject: onBoard !== null,
      ...fieldsOf(onBoard),
      html: html(t, t.body, opts),
    },
    comments: shown.map((c) => ({ id: c.id, url: c.url, author: c.author, createdAt: c.createdAt, html: html(c, c.body, opts) })),
    totalComments: t.totalComments,
    loadedComments: t.comments.length,
    needsDecision: decision,
    decisionStatus: config.decisionStatus,
    decision: summaryView(decisionSummary(t.comments), opts),
    // The owner's answer saved on this machine: waiting to be recorded, or the latest recorded one
    ownerAnswer: answerView(answerFor(await ownerAnswers(), want.repo, want.number)),
  })
}

/** A compact thread for agents: raw body, then newest comments first, without view-only HTML. */
async function readDiscussion({ item, comments }) {
  const want = parseItemRef(item, config.repository)
  const t = await thread(want.repo, want.number)
  const shown = t?.comments.slice(-Math.min(100, Math.max(1, Math.floor(comments ?? 20)))).reverse() ?? []
  if (!t) throw new GitHubError('not-found', `${refOf(want.repo, want.number)} is not an issue or pull request this GitHub login can see.`)
  const summary = `${refOf(want.repo, want.number)} ${t.title}: body and ${shown.length} newest of ${t.totalComments} comments.`
  const body = String(t.body ?? '').trim()
  const rows = shown.map((c) => `${c.createdAt ?? '?'} ${c.author}: ${c.body}`)
  return linesAnswer(summary, [['body', 'Body:', body ? [body] : ['(empty)']], ['comments', 'Comments, newest first:', rows]], {
    item: { ref: refOf(want.repo, want.number), type: t.type, state: t.state, url: t.url },
    totalComments: t.totalComments,
  })
}

/** A failed Actions job's log around its first failure, so agents do not need to fetch a whole run. */
async function readFailedJob({ job, repo }) {
  const r = repoOf(repo)
  const log = await readJobLog(r, job)
  const lines = cleanLog(log).map((line) => line.replace(/[ \t]+/g, ' '))
  const at = failureLineIndex(lines)
  const start = Math.max(0, (at < 0 ? 0 : at) - 8)
  const excerpt = lines.slice(start, Math.min(lines.length, start + 40))
  const summary = `Job ${job}: ${at < 0 ? 'no failure marker found' : `failure near line ${at + 1}`}; ${excerpt.length} log lines shown.`
  return linesAnswer(summary, [['log', '', excerpt]], { job: Number(job), startLine: start + 1 })
}

/** Runs `fn` over `list` with at most `n` at a time, answers in order. */
async function mapLimit(list, n, fn) {
  const out = new Array(list.length)
  let next = 0
  await Promise.all(
    Array.from({ length: Math.min(n, list.length) }, async () => {
      while (next < list.length) {
        const i = next++
        out[i] = await fn(list[i], i)
      }
    }),
  )
  return out
}

async function decisionSummaries({ refresh }) {
  const b = await board({ fresh: refresh === true })
  const decision = resolveOption(b.fields.status, config.decisionStatus).name
  const items = b.items.filter((i) => i.status === decision && i.number != null && i.repository).sort(byPriority)
  const saved = await ownerAnswers()
  const rows = await mapLimit(items, 4, async (i) => {
    const row = { ref: refOf(i.repository, i.number), repository: i.repository, number: i.number, title: i.title, url: i.url, type: i.type, ...fieldsOf(i), ownerAnswer: answerView(answerFor(saved, i.repository, i.number)) }
    try {
      const t = await thread(i.repository, i.number, { fresh: refresh === true })
      return { ...row, comments: t?.totalComments ?? 0, decision: t ? summaryView(decisionSummary(t.comments), renderOpts(t)) : null }
    } catch (e) {
      return { ...row, error: reason(e) }
    }
  })
  const without = rows.filter((r) => !r.error && !r.decision).length
  const summary = `${rows.length} item${rows.length === 1 ? '' : 's'} with Status ${decision}${without ? `, ${without} without a summary comment` : ''}.`
  return answer(summary, { ok: true, decisionStatus: decision, items: rows, fetchedAt: b.fetchedAt })
}

/**
 * Posts an agent's comment (the `comment` tool): not empty, in English, no word from the private list,
 * no attribution line. The owner's own answers never come through here: the screen saves them on
 * this machine (`save_answer`), and an agent records the decision in English (owner decision,
 * 2026-10-12: the repository is public).
 */
async function postItemComment({ item, body }) {
  const want = parseItemRef(item, config.repository)
  const ref = refOf(want.repo, want.number)
  const problems = String(body ?? '').trim() ? publicTextProblems(body, await privateWords(), 'The comment') : ['The comment is empty.']
  if (problems.length) throw new GitHubError('input', `Not posted on ${ref}: ${problems.join(' ')}`)
  const warnings = foreignBareIssueWarnings(body, want.repo, 'The comment')
  let c
  try {
    c = await postComment(want.repo, want.number, body)
  } finally {
    // Whether or not it went through, the cached thread can no longer be trusted
    forgetThread(want.repo, want.number)
  }
  const base = `https://github.com/${want.repo}/issues/${want.number}`
  return linesAnswer(`Posted a comment on ${ref}${c.url ? `: ${c.url}` : ''}.`, [['warnings', 'Warnings:', warnings]], {
    ok: true,
    ref,
    comment: { id: c.id, url: c.url, author: c.author, createdAt: c.createdAt, html: renderMarkdown(c.body, { repo: want.repo, base }) },
    ...(warnings.length ? { warnings } : {}),
  })
}

/** Edits only a comment belonging to the account gh is using, after all public-text checks pass. */
async function editItemComment({ item, url, body }) {
  const want = parseItemRef(item, config.repository)
  const ref = refOf(want.repo, want.number)
  const id = commentIdOf(url, want.repo, want.number)
  if (id.problem) throw new GitHubError('input', `Not edited: ${id.problem}`)
  const problems = String(body ?? '').trim() ? publicTextProblems(body, await privateWords(), 'The comment') : ['The comment is empty.']
  if (problems.length) throw new GitHubError('input', `Not edited on ${ref}: ${problems.join(' ')}`)
  const [before, me] = await Promise.all([readComment(want.repo, id.id), viewerLogin()])
  if (!before || before.number !== want.number) throw new GitHubError('input', `Not edited: GitHub has no comment ${id.id} on ${ref}.`)
  if (String(before.author).toLowerCase() !== String(me).toLowerCase()) throw new GitHubError('input', `Not edited: comment ${id.id} belongs to ${before.author}, not the gh account ${me}.`)
  const c = await editComment(want.repo, id.id, body)
  forgetThread(want.repo, want.number)
  const warnings = foreignBareIssueWarnings(body, want.repo, 'The comment')
  return linesAnswer(`Edited your comment on ${ref}${c.url ? `: ${c.url}` : ''}.`, [['warnings', 'Warnings:', warnings]], { ok: true, ref, comment: c })
}

// --- The owner's answers: on this machine, never on GitHub as written --------------------------------
// The screen saves the owner's answer to a "Needs decision" item in this app's data folder (outside
// the repository, which is public); an agent lists the answers not recorded yet, records each decision
// on its issue in English with `comment`, and marks the answer recorded with that comment's address.
const ANSWERS_FILE = 'owner-answers.json'
let answers = null
async function ownerAnswers() {
  answers ??= (await centralu.readJson(ANSWERS_FILE, { answers: [] }))?.answers ?? []
  return answers
}
async function keepAnswers(list) {
  await centralu.writeJson(ANSWERS_FILE, { answers: list })
  answers = list
}

/** What the screen and the decision lists show of an item's answer (null: none). */
const answerView = (a) => (a ? { text: a.text, savedAt: a.savedAt, updatedAt: a.updatedAt, recordedAt: a.recordedAt, recordedUrl: a.recordedUrl } : null)
const NOT_RECORDED = 'answered, not recorded yet'

async function titleOf(want, given) {
  if (given) return given
  const b = await board().catch(() => null)
  return b?.items.find(matches(want))?.title ?? null
}

async function saveOwnerAnswer({ item, text, title }) {
  const want = parseItemRef(item, config.repository)
  const ref = refOf(want.repo, want.number)
  let r
  try {
    r = saveAnswer(await ownerAnswers(), { repository: want.repo, number: want.number, title: await titleOf(want, title), text, now: new Date().toISOString() })
  } catch (e) {
    throw new GitHubError('input', `Not saved: ${e.message}`)
  }
  await keepAnswers(r.list)
  return answer(`${r.replaced ? 'Saved the changed answer' : 'Saved the answer'} on ${ref} on this computer only; nothing went to GitHub. An agent records the decision on ${ref} in English.`, {
    ok: true,
    ref,
    answer: answerView(r.answer),
  })
}

async function deleteOwnerAnswer({ item }) {
  const want = parseItemRef(item, config.repository)
  const ref = refOf(want.repo, want.number)
  let r
  try {
    r = deleteAnswer(await ownerAnswers(), want.repo, want.number)
  } catch (e) {
    throw new GitHubError('input', `Not deleted: ${ref}: ${e.message}`)
  }
  await keepAnswers(r.list)
  return answer(`Deleted the answer on ${ref}.`, { ok: true, ref, answer: answerView(answerFor(r.list, want.repo, want.number)) })
}

async function listOwnerAnswers({ all }) {
  const list = await ownerAnswers()
  const shown = all ? list : unrecorded(list)
  const lines = shown.map(
    (a) =>
      `${refOf(a.repository, a.number)}${a.title ? ` ${a.title}` : ''} — ${a.recordedAt ? `recorded ${a.recordedAt.slice(0, 10)}: ${a.recordedUrl}` : `${NOT_RECORDED}, saved ${(a.updatedAt ?? a.savedAt).slice(0, 16).replace('T', ' ')} UTC`}\n  ${a.text.replace(/\n/g, '\n  ')}`,
  )
  const waiting = unrecorded(list).length
  const summary = `${waiting} owner answer${waiting === 1 ? '' : 's'} not recorded yet${all ? `, ${list.length} kept` : ''}.${waiting ? ' For each: post the decision on its issue in English with comment, starting "**Decision (owner, YYYY-MM-DD):**" (CONTRIBUTING.md), then mark_answer_recorded with that comment\'s address.' : ''}`
  return linesAnswer(summary, [['answers', '', lines]], {
    count: waiting,
    items: shown.map((a) => ({ ref: refOf(a.repository, a.number), repository: a.repository, number: a.number, title: a.title, ...answerView(a) })),
  })
}

async function markOwnerAnswer({ item, url }) {
  const want = parseItemRef(item, config.repository)
  const ref = refOf(want.repo, want.number)
  const id = commentIdOf(url, want.repo, want.number)
  if (id.problem) throw new GitHubError('input', `Not marked: ${id.problem}`)
  const list = await ownerAnswers()
  if (!unrecorded(list).some((a) => answerKey(a.repository, a.number) === answerKey(want.repo, want.number))) throw new GitHubError('input', `Not marked: ${ref} has no answer waiting to be recorded.`)
  // The comment is read back: it exists, it is on this item, and it records the decision in English
  const c = await readComment(want.repo, id.id)
  const problems = []
  if (!c || c.number !== want.number) problems.push(`GitHub has no comment ${id.id} on ${ref}.`)
  else {
    if (!/Decision \(owner, \d{4}-\d{2}-\d{2}\)/.test(c.body)) problems.push('The comment does not hold "Decision (owner, YYYY-MM-DD)", the form a decision is recorded in (CONTRIBUTING.md).')
    problems.push(...englishProblems(c.body, 'The comment'))
  }
  if (problems.length) throw new GitHubError('input', `Not marked: ${problems.join(' ')}`)
  const r = markRecorded(list, want.repo, want.number, url, new Date().toISOString())
  await keepAnswers(r.list)
  return answer(`Marked the owner's answer on ${ref} recorded: ${url}`, { ok: true, ref, answer: answerView(r.answer) })
}

// --- The contribution procedure: public text, pull requests, commits, stacks (#386 step 2) ----------
// The rules come from the repository (the pull request template, the commit conventions) and the
// private word list from this app's data folder. Each tool refuses with the reasons and writes
// nothing when a rule fails; the checks run before the first call that changes anything on GitHub.

// The private word list: in the data folder, never in the repository (owner decision, 2026-10-06)
const WORDS_FILE = 'private-words.json'
const WORDS_MAX = 500
let words = null
async function privateWords() {
  words ??= normalizeWords((await centralu.readJson(WORDS_FILE, { words: [] }))?.words)
  return words
}
async function editPrivateWords({ add = [], remove = [] }) {
  const before = await privateWords()
  const gone = new Set(remove.map((w) => String(w).replace(/\s+/g, ' ').trim().toLowerCase()))
  const next = normalizeWords([...before.filter((w) => !gone.has(w.toLowerCase())), ...add])
  if (next.length > WORDS_MAX) throw new GitHubError('input', `The list would hold ${next.length} words; it keeps at most ${WORDS_MAX}. Nothing changed.`)
  const lower = new Set(before.map((w) => w.toLowerCase()))
  const added = next.filter((w) => !lower.has(w.toLowerCase()))
  const removed = before.filter((w) => gone.has(w.toLowerCase()))
  await centralu.writeJson(WORDS_FILE, { words: next })
  words = next
  return { words: next, added, removed }
}
const wordsAnswer = (list, head) => answer([head, ...list.map((w) => `- ${w}`)].join('\n'), { count: list.length, words: list }, head)
const wordCount = (n) => `${n} private word${n === 1 ? '' : 's'}`

// Where GitHub looks for a pull request template; project.json can name the one to use
const PR_TEMPLATES = ['.github/PULL_REQUEST_TEMPLATE.md', '.github/pull_request_template.md', 'PULL_REQUEST_TEMPLATE.md', 'docs/PULL_REQUEST_TEMPLATE.md']
const RULES = {
  prTemplates: config.rules?.prTemplate ? [config.rules.prTemplate, ...PR_TEMPLATES.filter((p) => p !== config.rules.prTemplate)] : PR_TEMPLATES,
  commitConventions: config.rules?.commitConventions ?? 'docs/commit-conventions.md',
}
const RULES_TTL_MS = 10 * 60_000
const ruleFiles = new Map() // `${repo} ${path} ${ref}` → { at, text }

/** A rules file from the repository on GitHub, kept 10 minutes; null when the repository has none. */
async function ruleFile(repo, path, ref) {
  const key = `${repo.toLowerCase()} ${path} ${ref}`
  const hit = ruleFiles.get(key)
  if (hit && Date.now() - hit.at < RULES_TTL_MS) return hit.text
  const text = await readRepoFile(repo, path, ref)
  ruleFiles.set(key, { at: Date.now(), text })
  return text
}

/** The commit conventions of `repo` (its default branch), or the usual ones with a note why. */
async function conventionsOf(repo) {
  const { defaultBranch } = await readRepo(repo)
  const text = await ruleFile(repo, RULES.commitConventions, defaultBranch)
  if (text === null) return { conventions: DEFAULT_CONVENTIONS, source: `the usual Conventional Commits rules (${repo} has no ${RULES.commitConventions})` }
  return { conventions: parseConventions(text), source: RULES.commitConventions }
}

const repoOf = (repo) => {
  const r = repo ?? config.repository
  if (!/^[\w.-]+\/[\w.-]+$/.test(String(r))) throw new GitHubError('input', `"${r}" is not a repository; give owner/name.`)
  return r
}

/** Refuses with every problem at once; warnings go along with a success. */
const refusal = (prefix, problems, extra = {}) => ({
  isError: true,
  ...linesAnswer(`${prefix} ${problems.length === 1 ? 'One rule fails' : `${problems.length} rules fail`}; nothing was sent to GitHub.`, [['problems', '', problems]], { ok: false, ...extra }),
})

async function commitCheck({ message, messages, repo }) {
  const list = messages ?? (message !== undefined ? [message] : null)
  if (!list?.length) throw new GitHubError('input', 'Give message (one commit message) or messages (several).')
  const r = repoOf(repo)
  const { conventions, source } = await conventionsOf(r)
  const privateList = await privateWords()
  const results = list.map((m) => ({ subject: String(m).split('\n')[0], ...commitProblems(m, conventions, privateList) }))
  const bad = results.filter((x) => x.problems.length)
  const lines = results.flatMap((x, n) => {
    const head = `${list.length > 1 ? `${n + 1}. ` : ''}"${x.subject}": ${x.problems.length ? 'refused' : 'ok'}`
    return [head, ...x.problems.map((p) => `  ${p}`), ...x.warnings.map((w) => `  (warning) ${w}`)]
  })
  const summary = bad.length ? `${bad.length} of ${list.length} refused by ${source}.` : `${list.length === 1 ? 'The message follows' : `All ${list.length} follow`} ${source}.`
  const a = linesAnswer(summary, [['results', '', lines]], { ok: bad.length === 0 })
  return bad.length ? { isError: true, ...a } : a
}

const PR_SECTIONS = { why: 'Why', whatChanged: 'What changed', verified: 'Verified', usability: 'Usability', notExercised: 'Not exercised', closes: 'Closes' }

async function openPr({ title, head, base, draft, repo, sections, dryRun, ...named }) {
  const r = repoOf(repo)
  const info = await readRepo(r)
  const target = base ?? info.defaultBranch
  let template = null
  for (const path of RULES.prTemplates) if ((template = await ruleFile(r, path, target)) !== null) break
  if (template === null) throw new GitHubError('setup', `${r} has no pull request template on ${target} to fill (looked for ${RULES.prTemplates.join(', ')}). Nothing was opened.`)
  const given = { ...sections }
  for (const [k, heading] of Object.entries(PR_SECTIONS)) if (named[k] !== undefined) given[heading] = named[k]
  const filled = fillTemplate(template, given)
  const { conventions } = await conventionsOf(r)
  const subject = subjectProblems(title, conventions)
  const list = await privateWords()
  const problems = [...subject.problems.map((p) => `Title: ${p}`), ...filled.problems, ...publicTextProblems(title, list, 'The title'), ...publicTextProblems(filled.body, list, 'The description')]
  const warnings = [...subject.warnings.map((w) => `Title: ${w}`), ...filled.warnings]
  // The squash commit's subject is "Title (#N)" (merge_when_green): it has to fit too
  const squashLength = [...String(title)].length + ' (#9999)'.length
  if (squashLength > conventions.subjectMax) warnings.push(`Merged, the subject "${title} (#N)" will be about ${squashLength} characters, over ${conventions.subjectMax}.`)
  if (problems.length) return refusal('Not opened:', problems, { warnings })
  if (dryRun) return linesAnswer(`Ready to open "${title}" from ${head} into ${target}${draft ? ' as a draft' : ''} (dry run, nothing sent).`, [['warnings', 'Warnings:', warnings]], { ok: true, body: filled.body })
  const pr = await createPr(r, { title, head, base: target, body: filled.body, draft })
  return linesAnswer(`Opened ${refOf(r, pr.number)} "${title}" from ${head} into ${target}${draft ? ' as a draft' : ''}: ${pr.url}`, [['warnings', 'Warnings:', warnings]], { ok: true, number: pr.number, url: pr.url })
}

async function fileIssue({ title, body, labels, repo, dryRun }) {
  const r = repoOf(repo)
  const list = await privateWords()
  const problems = [...(String(title ?? '').trim() ? [] : ['The title is empty.']), ...publicTextProblems(title, list, 'The title'), ...publicTextProblems(body, list, 'The body')]
  const warnings = foreignBareIssueWarnings(body, r, 'The body')
  if (problems.length) return refusal('Not filed:', problems)
  if (dryRun) return linesAnswer(`Ready to file "${title}" on ${r} (dry run, nothing sent).`, [['warnings', 'Warnings:', warnings]], { ok: true })
  const issue = await createIssue(r, { title, body, labels })
  return linesAnswer(`Filed ${refOf(r, issue.number)} "${title}": ${issue.url}`, [['warnings', 'Warnings:', warnings]], { ok: true, number: issue.number, url: issue.url })
}

// The checkout rebase_stack works from by default: the one this app is committed in
const APP_DIR = fileURLToPath(new URL('.', import.meta.url))

async function restack({ pr, lower, path, push }) {
  const want = parseItemRef(pr, config.repository)
  const below = lower === undefined ? undefined : parseItemRef(lower, want.repo)
  if (below && !sameRepo(below.repo, want.repo)) throw new GitHubError('input', 'lower must be a pull request of the same repository.')
  try {
    const r = await rebaseStack(
      { repo: want.repo, pr: want.number, lower: below?.number, dir: path ?? APP_DIR, push: push === true },
      { readPr, prsWithHead, setPrBase },
      (n) => refOf(want.repo, n),
    )
    return linesAnswer(r.summary, [['steps', '', r.lines]], { ok: !r.partial, pushed: r.pushed, head: r.rebased, sameTree: r.sameTree })
  } catch (e) {
    if (e instanceof StackRefusal || e instanceof GitError) return { isError: true, ...answer(`Not restacked: ${e.message}`, { ok: false, pushed: false }) }
    throw e
  }
}

// --- The release (#386 step 3) ------------------------------------------------------------------------
// docs/releasing.md as code: release.mjs holds the procedure, versions.mjs the version rules, and
// project.json `release` the repository's own layout (where the version is declared, which files carry
// it, the tag prefix, the workflow and its environment).
const RELEASE = releaseConfig(config.release)

/** main's CI, as ci_status reads it: every required check reported and passed is green. */
async function ciOfMain(repo, sha) {
  const { defaultBranch } = await readRepo(repo)
  const req = await readRequired(repo, defaultBranch, CI.workflows, workflowCheckNames)
  const checks = await evaluate(repo, sha, req)
  return { verdict: checks.verdict, summary: ciLines(defaultBranch, sha, req, checks).summary }
}

/** open_pr's own code, answering whether it went and what it said. */
async function openPrResult(args) {
  const a = await openPr(args)
  const s = a.structuredContent ?? {}
  return { ok: !a.isError && s.ok !== false, text: a.content?.[0]?.text ?? s.summary ?? '', number: s.number ?? null, url: s.url ?? null }
}

const RELEASE_STEPS = { bump: bumpRelease, rehearse: rehearseRelease, tag: tagRelease, approve: approveRelease, cancel_duplicate: cancelDuplicateRelease }
const RELEASE_GH = { readRepo, prsWithHead, workflowRuns, runJobs, pendingDeployments, approveDeployments, dispatchWorkflow, cancelWorkflowRun }

async function release(args, step) {
  const repo = config.repository
  const ctx = { repo, dir: args.path ?? APP_DIR, cfg: RELEASE, gh: RELEASE_GH, ci: (sha) => ciOfMain(repo, sha), openPr: openPrResult }
  try {
    if (step === 'status') {
      const r = await guarded(() => releaseStatus(ctx))
      return linesAnswer(r.summary, [['lines', '', r.lines]], { ok: true, phase: r.phase, version: r.version, tag: r.tag, head: r.head, duplicates: r.duplicates })
    }
    // Who is asking comes first, as for merging: a contributor's agent gets no further
    ctx.permissions = (await readRepo(repo)).permissions
    const { summary, lines, ...rest } = await guarded(() => RELEASE_STEPS[step](ctx, args))
    return linesAnswer(summary, [['lines', '', lines]], { ok: !rest.partial, step, ...rest })
  } catch (e) {
    if (!(e instanceof ReleaseRefusal)) throw e
    const n = e.problems.length
    return {
      isError: true,
      ...linesAnswer(`Release ${step} refused (${n === 1 ? 'one reason' : `${n} reasons`}); nothing was pushed, tagged, started or approved.`, [['problems', '', e.problems]], { ok: false, step }),
    }
  }
}

/**
 * The runtime's `uiResource`, with `_meta` on the resource and on its contents: Centralu reads a
 * view's CSP from the contents (the standard's place, docs/apps.md §6.4), and the runtime's helper
 * puts nothing there.
 */
function viewResource(server, name, uri, file, meta) {
  const withMeta = {
    registerResource: (n, u, cfg, read) =>
      server.registerResource(n, u, { ...cfg, _meta: meta }, async (...a) => {
        const r = await read(...a)
        return { ...r, contents: r.contents.map((c) => ({ ...c, _meta: { ...c._meta, ...meta } })) }
      }),
  }
  return centralu.uiResource(withMeta, name, uri, file)
}

